function isValid(s) {
  const pairs = { ')': '(', ']': '[', '}': '{' }; // closer -> opener
  const stack = [];
  for (const ch of s) {
    if (!(ch in pairs)) {
      stack.push(ch); // opening bracket: wait for its partner
    } else if (stack.length === 0 || stack.pop() !== pairs[ch]) {
      return false; // nothing to close, or the wrong type
    }
  }
  return stack.length === 0; // leftovers were never closed
}

def is_valid(s: str) -> bool:
    pairs = {')': '(', ']': '[', '}': '{'}  # closer -> opener
    stack = []
    for ch in s:
        if ch not in pairs:
            stack.append(ch)  # opening bracket: wait for its partner
        elif not stack or stack.pop() != pairs[ch]:
            return False  # nothing to close, or the wrong type
    return not stack  # leftovers were never closed

public boolean isValid(String s) {
    Map<Character, Character> pairs = Map.of(')', '(', ']', '[', '}', '{'); // closer -> opener
    Deque<Character> stack = new ArrayDeque<>();
    for (char ch : s.toCharArray()) {
        if (!pairs.containsKey(ch)) {
            stack.push(ch); // opening bracket: wait for its partner
        } else if (stack.isEmpty() || !stack.pop().equals(pairs.get(ch))) {
            return false; // nothing to close, or the wrong type
        }
    }
    return stack.isEmpty(); // leftovers were never closed
}

class MinStack {
  constructor() {
    this.stack = []; // entries: [value, minimum of the stack up to this entry]
  }

  push(x) {
    const min = this.stack.length === 0 ? x : Math.min(x, this.getMin());
    this.stack.push([x, min]);
  }

  pop() {
    this.stack.pop(); // the entry below already stores its own minimum
  }

  top() {
    return this.stack[this.stack.length - 1][0];
  }

  getMin() {
    return this.stack[this.stack.length - 1][1];
  }
}

