class MinStack {
    private final Deque<int[]> stack = new ArrayDeque<>(); // {value, min up to here}

    public void push(int x) {
        int min = stack.isEmpty() ? x : Math.min(x, stack.peek()[1]);
        stack.push(new int[] { x, min });
    }

