    }
}

function evalRPN(tokens) {
  const stack = [];
  for (const t of tokens) {
    if (t === '+' || t === '-' || t === '*' || t === '/') {
      const b = stack.pop(); // right operand was pushed last
      const a = stack.pop();
      if (t === '+') stack.push(a + b);
      else if (t === '-') stack.push(a - b);
      else if (t === '*') stack.push(a * b);
      else stack.push(Math.trunc(a / b)); // truncate toward zero
    } else {
      stack.push(Number(t)); // operand: wait for its operator
    }
  }
  return stack.pop(); // the single remaining value is the answer
}

def eval_rpn(tokens: list[str]) -> int:
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()  # right operand was pushed last
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:
                stack.append(int(a / b))  # truncate toward zero; // would floor
        else:
            stack.append(int(t))  # operand: wait for its operator
    return stack.pop()

public int evalRPN(String[] tokens) {
    Deque<Integer> stack = new ArrayDeque<>();
    for (String t : tokens) {
        switch (t) {
            case "+", "-", "*", "/" -> {
                int b = stack.pop(); // right operand was pushed last
                int a = stack.pop();
                stack.push(switch (t) {
                    case "+" -> a + b;
                    case "-" -> a - b;
                    case "*" -> a * b;
                    default -> a / b; // int division truncates toward zero
                });
            }
            default -> stack.push(Integer.parseInt(t)); // operand
        }
    }
    return stack.pop();
}

function dailyTemperatures(temps) {
  const answer = new Array(temps.length).fill(0);
  const stack = []; // indices of days still waiting for a warmer day
  for (let i = 0; i < temps.length; i++) {
    while (stack.length > 0 && temps[i] > temps[stack[stack.length - 1]]) {
      const j = stack.pop(); // day i is the first warmer day after day j
      answer[j] = i - j;
    }
    stack.push(i); // day i now waits for its own warmer day
  }
  return answer; // days left on the stack keep 0
}

