function nextGreater(nums) {
  const result = new Array(nums.length).fill(-1);
  const stack = []; // values to the right that could still be an answer
  for (let i = nums.length - 1; i >= 0; i--) {
    while (stack.length > 0 && stack[stack.length - 1] <= nums[i]) {
      stack.pop(); // hidden behind nums[i]: can never be an answer again
    }
    if (stack.length > 0) result[i] = stack[stack.length - 1];
    stack.push(nums[i]); // nums[i] is a candidate for elements to its left
  }
  return result;
}

