    stack = []  # values to the right that could still be an answer
    for i in range(len(nums) - 1, -1, -1):
        while stack and stack[-1] <= nums[i]:
            stack.pop()  # hidden behind nums[i]: can never be an answer again
        if stack:
            result[i] = stack[-1]
        stack.append(nums[i])  # candidate for elements to its left
    return result

public int[] nextGreater(int[] nums) {
    int[] result = new int[nums.length];
    Deque<Integer> stack = new ArrayDeque<>(); // candidate values to the right
    for (int i = nums.length - 1; i >= 0; i--) {
        while (!stack.isEmpty() && stack.peek() <= nums[i]) {
            stack.pop(); // hidden behind nums[i]: can never be an answer again
        }
        result[i] = stack.isEmpty() ? -1 : stack.peek();
        stack.push(nums[i]); // candidate for elements to its left
    }
    return result;
}

