    private final Deque<Integer> outbox = new ArrayDeque<>(); // front on top

    public void push(int x) {
        inbox.push(x);
    }

    public int pop() {
        peek(); // make sure the front element is on top of outbox
        return outbox.pop();
    }

    public int peek() {
        if (outbox.isEmpty()) { // transfer only when outbox is empty
            while (!inbox.isEmpty()) outbox.push(inbox.pop());
        }
