function largestRectangleArea(heights) {
  const stack = []; // indices of bars, heights increasing bottom -> top
  let best = 0;
  for (let i = 0; i <= heights.length; i++) {
    const h = i === heights.length ? 0 : heights[i]; // height-0 sentinel flushes the stack
    while (stack.length > 0 && heights[stack[stack.length - 1]] > h) {
      const height = heights[stack.pop()]; // this bar is the shortest of its rectangle
      const left = stack.length > 0 ? stack[stack.length - 1] : -1; // first lower bar on the left
      const width = i - left - 1; // bar i is the first lower bar on the right
      best = Math.max(best, height * width);
    }
    stack.push(i);
  }
  return best;
}

public int largestRectangleArea(int[] heights) {
    Deque<Integer> stack = new ArrayDeque<>(); // indices, heights increasing
    int best = 0, n = heights.length;
    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i]; // height-0 sentinel flushes the stack
        while (!stack.isEmpty() && heights[stack.peek()] > h) {
            int height = heights[stack.pop()]; // shortest bar of its rectangle
            int left = stack.isEmpty() ? -1 : stack.peek(); // first lower bar on the left
            int width = i - left - 1; // bar i is the first lower bar on the right
            best = Math.max(best, height * width);
        }
        stack.push(i);
    }
    return best;
}

