  constructor(capacity) {
    this.buf = new Array(capacity);
    this.head = 0; // index of the front element
    this.size = 0;
  }

  enqueue(x) {
    if (this.size === this.buf.length) return false; // full
    const tail = (this.head + this.size) % this.buf.length; // wrap around
    this.buf[tail] = x;
    this.size++;
    return true;
  }

  dequeue() {
    if (this.size === 0) return undefined; // empty
    const x = this.buf[this.head];
    this.head = (this.head + 1) % this.buf.length; // wrap around
    this.size--;
    return x;
  }
}

