        return x

class CircularQueue {
    private final int[] buf;
    private int head = 0; // index of the front element
    private int size = 0;

    CircularQueue(int capacity) {
        buf = new int[capacity];
    }

    boolean enqueue(int x) {
        if (size == buf.length) return false; // full
        int tail = (head + size) % buf.length; // wrap around
        buf[tail] = x;
        size++;
        return true;
    }

    Integer dequeue() {
        if (size == 0) return null; // empty
        int x = buf[head];
        head = (head + 1) % buf.length; // wrap around
        size--;
        return x;
    }
}

